# Generated by test-lab — blind adversarial evaluation
"""Ledger-aware resolver contract: refinements revise one question id and
answered questions are never re-emitted as new cards."""

from __future__ import annotations

import pytest

from live_evidence.config import AppSettings, InterviewProfile
from live_evidence.models import (
    EvidenceCard,
    EvidenceSource,
    Freshness,
    RetrievalLane,
)
from live_evidence.readiness import ReadinessVerdict
from live_evidence.resolver import PROMPT_BUFFER_LABEL, PROMPT_HEADER
from live_evidence.state import RuntimeState


def _state() -> "RuntimeState":
    return RuntimeState(AppSettings.from_env(), InterviewProfile(name="ledger-test"))


def _card(question_id: str, question: str, answer: str | None) -> EvidenceCard:
    return EvidenceCard(
        card_id=f"card-{question_id}",
        query=question,
        thread="test · thread",
        question=question,
        answer=answer,
        talking_point="tp",
        proof="proof",
        qualifier="verified against fixture",
        confidence=0.9,
        status="supported",
        sources=[
            EvidenceSource(
                source_id=f"src-{question_id}",
                lane=RetrievalLane.MEMORY,
                label="label",
                excerpt="excerpt",
                score=1.0,
                path="/tmp/ledger-test-source.md",
                freshness=Freshness.CURRENT,
                metadata={},
            )
        ],
        lanes=[RetrievalLane.MEMORY],
        clarifications=[],
        question_id=question_id,
        question_revision=1,
    )


@pytest.mark.asyncio
async def test_question_ledger_reports_answered_state() -> None:
    state = _state()
    await state.start_session(consent_confirmed=True)
    qid, _rev = await state.revise_question("Which nodes may run in parallel?")
    state._cards = [  # noqa: SLF001 - direct fixture injection
        _card(qid, "Which nodes may run in parallel?", None),
        _card("q_answered", "How do you keep pipelines auditable?", "Log every stage."),
    ]
    ledger = await state.question_ledger()
    by_id = {entry["id"]: entry for entry in ledger}
    assert by_id[qid]["answered"] is False
    assert by_id["q_answered"]["answered"] is True
    assert by_id[qid]["text"] == "Which nodes may run in parallel?"


@pytest.mark.asyncio
async def test_adopt_question_revises_matched_id_in_place() -> None:
    state = _state()
    await state.start_session(consent_confirmed=True)
    original_id, first_revision = await state.revise_question("Which nodes may run?")
    assert first_revision == 1
    adopted_id, revision = await state.adopt_question(
        original_id, "Which nodes may run in parallel, which transitions require serialization?"
    )
    assert adopted_id == original_id
    assert revision == 2
    ledger = await state.question_ledger()
    assert ledger[0]["id"] == original_id
    assert "serialization" in str(ledger[0]["text"])


def test_verdict_parses_ledger_fields() -> None:
    verdict = ReadinessVerdict.model_validate(
        {
            "ready_to_answer": False,
            "blocking_reason": "already_answered",
            "question_type": "code",
            "canonical_question": "How do you keep pipelines auditable?",
            "matches_question_id": "q_answered",
            "already_answered": True,
        }
    )
    assert verdict.matches_question_id == "q_answered"
    assert verdict.already_answered is True
    assert verdict.blocking_reason == "already_answered"


def test_prompt_carries_ledger_contract() -> None:
    assert "matches_question_id" in PROMPT_HEADER
    assert "already_answered" in PROMPT_HEADER
    assert "KNOWN_QUESTIONS" in PROMPT_HEADER
    assert PROMPT_BUFFER_LABEL.strip() == "BUFFER:"
    # Gating keys must stay first for the streaming gate regex.
    assert PROMPT_HEADER.index('"ready_to_answer"') < PROMPT_HEADER.index("matches_question_id")
